const __util = (() => {
// Shared constants and small pure helpers for the engine. No DOM, no network, no clock.

const PATTERNS = ['SQ', 'HI', 'SL', 'HP', 'VP', 'HR', 'VR', 'CA', 'CO', 'BA', 'HA', 'AR'];
const LOWER_PATTERNS = new Set(['SQ', 'HI', 'SL']);
const AREAS = ['knees', 'hips', 'low_back', 'upper_back_neck', 'shoulders', 'elbows_wrists'];
const AGE_BANDS = ['40-49', '50-59', '60-69', '70+'];

/** "8-12" → {lo: 8, hi: 12}; "3" → {lo: 3, hi: 3}. */
function parseRange(value) {
  const s = String(value ?? '').trim();
  const m = /^(\d+)-(\d+)$/.exec(s);
  if (m) return { lo: Number(m[1]), hi: Number(m[2]) };
  if (/^\d+$/.test(s)) return { lo: Number(s), hi: Number(s) };
  throw new Error(`Not a range: ${JSON.stringify(value)}`);
}

const formatRange = ({ lo, hi }) => (lo === hi ? String(lo) : `${lo}-${hi}`);

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));

/** Age band of 60+ (60-69 or 70+). */
const isSixtyPlus = (band) => band === '60-69' || band === '70+';

// ── Dates: always ISO 'YYYY-MM-DD' strings, computed in UTC so time zones can't shift a day. ──
const toUtc = (iso) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) throw new Error(`Not an ISO date: ${iso}`);
  const [y, m, d] = iso.split('-').map(Number);
  return Date.UTC(y, m - 1, d);
};
const fromUtc = (ms) => new Date(ms).toISOString().slice(0, 10);

const addDays = (iso, n) => fromUtc(toUtc(iso) + n * 86400000);
const daysBetween = (fromIso, toIso) => Math.round((toUtc(toIso) - toUtc(fromIso)) / 86400000);
/** ISO weekday: 1 = Monday … 7 = Sunday. */
const isoWeekday = (iso) => ((new Date(toUtc(iso)).getUTCDay() + 6) % 7) + 1;
/** Monday of the week containing iso. */
const mondayOf = (iso) => addDays(iso, 1 - isoWeekday(iso));
return { PATTERNS, LOWER_PATTERNS, AREAS, AGE_BANDS, parseRange, formatRange, clamp, isSixtyPlus, addDays, daysBetween, isoWeekday, mondayOf };
})();

// ── web/engine/resolve.js ──
const __resolve = (() => {
// Slot → exercise resolution (Framework §5.2, §9, §11, §16).
// Given a template slot, the patient's profile and the exercise library, pick the exercise she does,
// and say why it differs from the "ideal" pick (equipment, a work-around, a restriction or floor comfort),
// so the app can show "Swapped: no barbell in your setup" style notes.
//
// Profile shape (all fields optional except equipment):
//   { equipment: ['db','bench',…], patternLevels: {SQ: 2, …}, workarounds: ['knees'],
//     restrictions: ['overhead'], floorOk: false }

const { AREAS } = __util;
/** Equipment requirement: ';' separates items that are all required, '|' separates alternatives. */
function equipOk(requirement, have) {
  const set = have instanceof Set ? have : new Set(have);
  return String(requirement || 'none')
    .split(';').filter(Boolean)
    .every((group) => group.split('|').some((alt) => alt === 'none' || set.has(alt)));
}

/**
 * Could this exercise fill a slot for this patient? Each test can be switched off (ignore.*) so we can ask
 * "what would she get without this constraint?" when explaining a swap.
 */
function eligible(ex, ctx, ignore = {}) {
  if (!ex.active) return false;
  if (ex.level > ctx.level) return false;
  if (!ignore.equipment && !equipOk(ex.equipment, ctx.have)) return false;
  if (!ignore.restrictions && (ex.restrictions || []).some((r) => ctx.restrictions.has(r))) return false;
  if (!ignore.floor && ex.floor && !ctx.floorOk && ctx.level < 3) return false;
  if (!ignore.workarounds) {
    for (const area of ctx.workarounds) if ((ex.area_load?.[area] ?? 0) > 1) return false;
  }
  return true;
}

function rank(slot, used) {
  const prefer = slot.prefer_ids || [];
  const pIdx = (id) => { const i = prefer.indexOf(id); return i === -1 ? Infinity : i; };
  return (a, b) =>
    (pIdx(a.id) - pIdx(b.id)) ||                                   // template preference first
    ((used.has(a.id) ? 1 : 0) - (used.has(b.id) ? 1 : 0)) ||      // something not already in this week
    (b.level - a.level) ||                                         // highest level she's ready for
    a.id.localeCompare(b.id);                                      // stable
}

/** Build the filtering context for a slot. */
function contextFor(slot, profile, opts = {}) {
  const base = profile.patternLevels?.[slot.pattern] ?? 1;
  return {
    level: Math.max(1, base + (opts.levelDelta ?? 0)),
    have: new Set(['none', ...(profile.equipment || [])]),
    restrictions: new Set(profile.restrictions || []),
    workarounds: new Set([...(profile.workarounds || []), ...(opts.todayWorkarounds || [])]),
    floorOk: Boolean(profile.floorOk),
  };
}

/**
 * Pick the exercise for one slot.
 * @returns {{exercise: object|null, level: number, reasons: Array<{type: string, area?: string, instead?: string}>}}
 *   reasons explain differences from the unconstrained pick: type 'equipment' | 'workaround' | 'restriction' | 'floor'
 *   | 'no-option' (nothing fits: the engine skips the slot, Framework §9).
 */
function resolveSlot(slot, profile, library, opts = {}) {
  const used = opts.used ?? new Set();
  const ctx = contextFor(slot, profile, opts);
  const pool = library.filter((e) => e.pattern === slot.pattern);
  const order = rank(slot, used);
  const pick = (ignore) => pool.filter((e) => eligible(e, ctx, ignore)).sort(order)[0] ?? null;

  const chosen = pick({});
  if (!chosen) return { exercise: null, level: ctx.level, reasons: [{ type: 'no-option' }] };

  const reasons = [];
  const explain = (type, ignore) => {
    const alt = pick(ignore);
    if (alt && alt.id !== chosen.id) reasons.push({ type, instead: alt.id, ...areaOf(type, alt, ctx) });
  };
  explain('equipment', { equipment: true });
  explain('workaround', { workarounds: true });
  explain('restriction', { restrictions: true });
  explain('floor', { floor: true });
  return { exercise: chosen, level: ctx.level, reasons };
}

function areaOf(type, alt, ctx) {
  if (type !== 'workaround') return {};
  const area = AREAS.find((a) => ctx.workarounds.has(a) && (alt.area_load?.[a] ?? 0) > 1);
  return area ? { area } : {};
}

/**
 * Resolve every slot of one session that fits her session length, in order.
 * `used` is shared across the week's sessions so the same pattern gets a different exercise when possible.
 */
function resolveSession(sessionSlots, profile, library, opts = {}) {
  const minutes = opts.minutes ?? 45;
  const used = opts.used ?? new Set();
  return [...sessionSlots]
    .filter((s) => s.min_minutes <= minutes)
    .sort((a, b) => a.ord - b.ord)
    .map((slot) => {
      const r = resolveSlot(slot, profile, library, { ...opts, used });
      if (r.exercise) used.add(r.exercise.id);
      return { slot, ...r };
    });
}

/**
 * Plain-language note for a swap (shown once under the exercise name). Equipment matching is the normal case for
 * home setups, so it is only spelled out when asked (admin view, or right after she changes her equipment).
 */
function swapNote(reasons, { includeEquipment = false } = {}) {
  const r = reasons.find((x) => x.type !== 'no-option' && (includeEquipment || x.type !== 'equipment'));
  if (!r) return '';
  const area = (r.area || '').replace(/_/g, ' ').replace('upper back neck', 'upper back and neck').replace('elbows wrists', 'elbows and wrists');
  switch (r.type) {
    case 'equipment': return 'Matched to the equipment you have.';
    case 'workaround': return area ? `Giving your ${area} a break. Here's your swap.` : "Here's your swap.";
    case 'restriction': return 'Chosen to fit what your provider asked you to avoid.';
    case 'floor': return 'A version that stays off the floor.';
    default: return '';
  }
}
return { equipOk, eligible, contextFor, resolveSlot, resolveSession, swapNote };
})();

// ── web/engine/adherence.js ──
const __adherence = (() => {
// Adherence (the product's proof), forgiving streaks, comebacks and clinic flags (Framework §13; Brad's spec).

const { daysBetween } = __util;
const DEFAULTS = { 'comeback.welcome_back_days': 8, 'comeback.reentry_days': 14, 'comeback.restart_days': 28 };
const cfg = (s, k) => (s && s[k] != null ? Number(s[k]) : DEFAULTS[k]);

/** Completed ÷ planned (skipped-with-reason sessions still count as planned). 0–1, or null if nothing planned. */
function adherence(planned, completed) {
  return planned ? Math.min(1, completed / planned) : null;
}

/**
 * Forgiving streak ("never two in a row"): walk planned sessions from newest to oldest; a single miss doesn't
 * break the streak, two misses in a row do. Returns sessions completed in the current streak.
 * sessions: chronological [{ date, done: boolean }] of planned sessions up to today.
 */
function forgivingStreak(sessions) {
  let streak = 0;
  let misses = 0;
  for (let i = sessions.length - 1; i >= 0; i--) {
    if (sessions[i].done) { streak += 1; misses = 0; continue; }
    misses += 1;
    if (misses >= 2) break;
  }
  return streak;
}

/** Best forgiving streak ever (for the progress view). */
function bestStreak(sessions) {
  let best = 0;
  for (let end = 0; end < sessions.length; end++) best = Math.max(best, forgivingStreak(sessions.slice(0, end + 1)));
  return best;
}

/**
 * Comeback mode from the gap since her last completed session (§13).
 * @returns {{mode: 'none'|'welcome_back'|'reentry'|'restart', setDelta: number, loadCutPct: number, sessions: number}}
 */
function comebackMode(lastSessionDate, today, settings) {
  if (!lastSessionDate) return { mode: 'none', setDelta: 0, loadCutPct: 0, sessions: 0 };
  const gap = daysBetween(lastSessionDate, today);
  if (gap >= cfg(settings, 'comeback.restart_days')) return { mode: 'restart', setDelta: 0, loadCutPct: 20, sessions: 0 };
  if (gap >= cfg(settings, 'comeback.reentry_days')) return { mode: 'reentry', setDelta: -1, loadCutPct: 15, sessions: 2 };
  if (gap >= cfg(settings, 'comeback.welcome_back_days')) return { mode: 'welcome_back', setDelta: -1, loadCutPct: 10, sessions: 1 };
  return { mode: 'none', setDelta: 0, loadCutPct: 0, sessions: 0 };
}

/** Clinic "worth a check-in call" flag: no completed workout in 7 days (enrolled, past her start date). */
function needsCheckInCall(lastSessionDate, startDate, today, days = 7) {
  const since = lastSessionDate ?? startDate;
  return since ? daysBetween(since, today) >= days : false;
}

/** Slipping: under 50% of planned sessions over the last 2 weeks (admin view; earlier signal than the call flag). */
function isSlipping(planned2w, completed2w) {
  return planned2w > 0 && completed2w / planned2w < 0.5;
}
return { DEFAULTS, adherence, forgivingStreak, bestStreak, comebackMode, needsCheckInCall, isSlipping };
})();

// ── web/engine/cycle.js ──
const __cycle = (() => {
// Cycle mechanics (Framework §7): week of cycle, the adaptive week-4 / week-9 decision (§7.2a), weekly dose,
// the session queue, and materializing a cycle (exercise per slot, fixed for the cycle).

const { daysBetween, parseRange } = __util;
const { resolveSession } = __resolve;
const DEFAULTS = {
  'adaptive.consistent_pct': 75,
  'adaptive.too_hard_count': 2,
  'adaptive.low_energy_count': 2,
  'adaptive.flag_count': 3,
  'adaptive.stalled_primaries': 2,
  'lighter_week.set_cut_pct': 45,
};
const cfg = (settings, k) => (settings && settings[k] != null ? Number(settings[k]) : DEFAULTS[k]);

/** Week 1–9 of a cycle that started on cycleStart (ISO date). 0 before the start; 10+ after the transition week. */
function weekOfCycle(cycleStart, today) {
  const d = daysBetween(cycleStart, today);
  return d < 0 ? 0 : Math.floor(d / 7) + 1;
}

/** Completed ≥ X% of planned sessions (§7.2a "consistent"). */
function isConsistent(planned, completed, settings) {
  if (!planned) return false;
  return (completed / planned) * 100 >= cfg(settings, 'adaptive.consistent_pct');
}

/**
 * "Needs rest" signals over the last 2 weeks (§7.2a). Any one is enough.
 * signals: { tooHard, lowEnergy, flags, stalledPrimaries } (counts)
 */
function needsRest(signals = {}, settings) {
  const reasons = [];
  if ((signals.tooHard ?? 0) >= cfg(settings, 'adaptive.too_hard_count')) reasons.push('too_hard');
  if ((signals.lowEnergy ?? 0) >= cfg(settings, 'adaptive.low_energy_count')) reasons.push('low_energy');
  if ((signals.flags ?? 0) >= cfg(settings, 'adaptive.flag_count')) reasons.push('soreness_flags');
  if ((signals.stalledPrimaries ?? 0) >= cfg(settings, 'adaptive.stalled_primaries')) reasons.push('stalled');
  return reasons;
}

/**
 * The adaptive week decision (§7.2a). Weeks other than 4 and 9 are 'build'.
 * @returns {{mode: string, consistent: boolean, restReasons: string[]}}
 *   week 4: 'build' | 'consolidate' | 'lighter'      week 9: 'normal' | 'light' | 'deload'
 */
function adaptiveWeekMode({ week, planned, completed, signals, settings }) {
  const consistent = isConsistent(planned, completed, settings);
  const restReasons = consistent ? needsRest(signals, settings) : [];
  let mode = 'build';
  if (week === 4) mode = !consistent ? 'build' : restReasons.length ? 'lighter' : 'consolidate';
  if (week === 9) mode = !consistent ? 'normal' : restReasons.length ? 'deload' : 'light';
  return { mode, consistent, restReasons };
}

/** Patient-facing explanation of a week-4/9 decision. */
function weekModeMessage(mode) {
  return {
    consolidate: 'You’ve been consistent. This week we hold your weights steady and make every rep smooth.',
    lighter: 'You’ve trained consistently and your body’s been working hard, so this week is lighter. That’s how strength sticks.',
    light: 'Great cycle. This week is a little lighter while we look back and plan your next one.',
    deload: 'You’ve earned an easier week. Lighter sessions now help the next cycle go even better.',
    normal: 'Let’s use this week to get back in rhythm, then plan your next cycle together.',
    build: '',
  }[mode] ?? '';
}

/**
 * Dose for one slot in a given week (1–9) and week mode.
 * Week 9 starts from week 8's prescription. Lighter / deload: sets cut ~45% (min 1), RIR 3–4.
 * Light: −1 set (min 1), RIR 3. Consolidate/normal/build: as written (load module handles "no increases").
 */
function slotDose(slot, week, mode = 'build', settings) {
  const i = Math.min(Math.max(week, 1), 8) - 1;
  let sets = Number(slot.sets_by_week[i]);
  let rir = String(slot.rir_by_week[i]);
  const reps = parseRange(slot.reps_by_week[i]);
  const time = slot.time_range_sec ? parseRange(slot.time_range_sec) : null;
  if (mode === 'lighter' || mode === 'deload') {
    sets = Math.max(1, Math.round(sets * (1 - cfg(settings, 'lighter_week.set_cut_pct') / 100)));
    rir = '3-4';
  } else if (mode === 'light') {
    sets = Math.max(1, sets - 1);
    rir = '3';
  }
  return { sets, reps, rir, time, restSec: slot.rest_sec };
}

/** Next session letter in this week's queue, or null when the week is done. Order follows the template. */
function nextInQueue(sessionOrder, completedThisWeek) {
  const done = new Set(completedThisWeek);
  return sessionOrder.find((s) => !done.has(s)) ?? null;
}

/**
 * Materialize a cycle for a patient: resolve every slot once (exercise fixed for the cycle; the same pattern
 * twice in a week gets a different exercise when possible). opts.used: exercises to steer away from when
 * there's a choice (a repeated cycle type gets fresh exercises, Framework §14).
 * @returns {{templateId, sessions: Array<{session, name, items: Array<{slot, exercise, reasons}>}>, skipped: number}}
 */
function materializeCycle(template, slots, profile, library, { minutes = 45, used: avoid = [] } = {}) {
  const used = new Set(avoid);
  let skipped = 0;
  const sessions = template.sessions.map(({ session, name }) => {
    const own = slots.filter((s) => s.template_id === template.template_id && s.session === session);
    const items = resolveSession(own, profile, library, { minutes, used });
    skipped += items.filter((it) => !it.exercise).length;
    return { session, name, items };
  });
  return { templateId: template.template_id, sessions, skipped };
}

/** Which template fits this patient (Framework §11.1): cycle type + days per week; 4-day only if experienced. */
function chooseTemplate(templates, { cycleType, daysPerWeek, experienced }) {
  const days = daysPerWeek === 4 && !experienced ? 3 : daysPerWeek;
  return templates.find((t) => t.active && t.cycle_type === cycleType && t.days_per_week === days)
    ?? templates.find((t) => t.active && t.cycle_type === cycleType && t.days_per_week === 3)
    ?? null;
}
return { DEFAULTS, weekOfCycle, isConsistent, needsRest, adaptiveWeekMode, weekModeMessage, slotDose, nextInQueue, materializeCycle, chooseTemplate };
})();

// ── web/engine/load.js ──
const __load = (() => {
// Load prescription (Framework §8): "find your weight", double progression, increments by load type and age band.
// Weights are in pounds. Bands use a resistance level (1 = extra light … 5 = extra heavy). Bodyweight progresses by
// reps, then tempo, then a level-up offer.

const { isSixtyPlus } = __util;
const DB_STEPS = [2, 3, 5, 8, 10, 12, 15, 17.5, 20, 22.5, 25, 30, 35, 40, 45, 50, 55, 60, 65, 70, 75, 80, 90, 100];
const KB_STEPS = [9, 13, 18, 26, 35, 44, 53, 62, 70];
const BAND_LABELS = ['', 'Extra light', 'Light', 'Medium', 'Heavy', 'Extra heavy'];
const DEFAULTS = {
  'progression.max_load_jump_pct': 10,
  'progression.max_increments_per_week': 2,
  'progression.double_jump_extra_reps': 3,
  'progression.drop_pct': 10,
  'scale_today.load_cut_pct': 10,
};
const set = (settings, k) => (settings && settings[k] != null ? Number(settings[k]) : DEFAULTS[k]);

/** The weights she can load: her own dumbbell set (opts.available) applies to dumbbells only. */
function weightsFor(loadType, opts = {}) {
  if (loadType === 'dumbbell' && opts.available?.length) return [...opts.available].sort((a, b) => a - b);
  return stepList(loadType);
}

function stepList(loadType) {
  if (loadType === 'dumbbell') return DB_STEPS;
  if (loadType === 'kettlebell') return KB_STEPS;
  if (loadType === 'band') return [1, 2, 3, 4, 5];
  return null;
}

/** Linear increment for stack / bar loads (Framework §8.3). */
function linearStep(loadType, { lower, ageBand }) {
  const fifty = ageBand && ageBand !== '40-49';
  if (loadType === 'machine' || loadType === 'cable') return 5;
  if (loadType === 'barbell') return lower ? (fifty ? 5 : 10) : (fifty ? 2.5 : 5);
  return null;
}

/**
 * Move a weight n steps up (n > 0) or down (n < 0). Returns the same weight when it can't move
 * (bodyweight, or the end of the dumbbell rack). `available` optionally limits the steps (e.g. home dumbbells).
 */
function step(loadType, weight, n, opts = {}) {
  if (loadType === 'bodyweight' || weight == null || n === 0) return weight;
  const list = weightsFor(loadType, opts);
  if (list) {
    let i = list.findIndex((w) => w >= weight - 1e-9);
    if (i === -1) i = list.length - 1;
    if (list[i] > weight + 1e-9 && n > 0) n -= 1;   // weight between steps: first step up lands on the next one
    return list[Math.max(0, Math.min(list.length - 1, i + n))];
  }
  const inc = linearStep(loadType, opts);
  return Math.max(0, Math.round((weight + n * inc) * 2) / 2);
}

/** Round down to a weight she can actually load (used by Scale today / drops). */
function roundDownToStep(loadType, weight, opts = {}) {
  const list = weightsFor(loadType, opts);
  if (list) return [...list].reverse().find((w) => w <= weight + 1e-9) ?? list[0];
  const inc = linearStep(loadType, opts) || 1;
  return Math.floor(weight / inc) * inc;
}

/**
 * First exposure: she did set 1 at `weight` and rated it. Weight for the remaining sets (Framework §8.1).
 * rating: 'easy' | 'good' | 'hard'; muchEasier: she said she could have done many more.
 */
function findYourWeight({ loadType, weight, rating, muchEasier = false, lower = false, ageBand, available }) {
  const opts = { lower, ageBand, available };
  if (rating === 'easy') return { weight: step(loadType, weight, muchEasier ? 2 : 1, opts), note: 'A little heavier for the next sets.' };
  if (rating === 'hard') return { weight: step(loadType, weight, -1, opts), note: 'A little lighter for the next sets.' };
  return { weight, note: 'That’s your weight. Same for the next sets.' };
}

/**
 * Double progression (Framework §8.2). Given the last session on this exercise, suggest the next one.
 * last: { weight, sets: [{reps}], rating: 'easy'|'good'|'hard' }   prevRating: rating the time before (or null)
 * range: { lo, hi }   weekMode: 'build' | 'normal' | 'consolidate' | 'lighter' | 'light' | 'deload'
 * Returns { weight, action: 'find'|'increase'|'hold'|'decrease'|'progress-bodyweight'|'level-up-check', targetReps, note }
 */
function suggestNext({ loadType, last, prevRating = null, range, ageBand, lower = false, weekMode = 'build',
  earlyFoundations = false, settings, available }) {
  const opts = { lower, ageBand, available };
  if (!last || !last.sets?.length) {
    return { weight: null, action: 'find', targetReps: range.hi, note: 'Find your weight: pick one you could lift about 12–15 times and do 10.' };
  }
  const reps = last.sets.map((s) => Number(s.reps) || 0);
  const w = last.weight;
  const allTop = reps.every((r) => r >= range.hi);
  const anyBelow = reps.some((r) => r < range.lo);
  const holdWeek = ['consolidate', 'lighter', 'light', 'deload'].includes(weekMode);
  const nextReps = Math.min(range.hi, Math.max(range.lo, Math.min(...reps) + 1));

  if (anyBelow || (last.rating === 'hard' && prevRating === 'hard')) {
    if (loadType === 'bodyweight') return { weight: w, action: 'level-down-check', targetReps: range.lo, note: 'Let’s make this one a little easier.' };
    const byPct = roundDownToStep(loadType, w * (1 - set(settings, 'progression.drop_pct') / 100), opts);
    const oneDown = step(loadType, w, -1, opts);
    return { weight: Math.min(byPct, oneDown), action: 'decrease', targetReps: range.lo, note: 'A little lighter this time. That’s smart training.' };
  }
  if (holdWeek) return { weight: w, action: 'hold', targetReps: nextReps, note: 'Holding steady this week.' };
  if (last.rating === 'hard') return { weight: w, action: 'hold', targetReps: nextReps, note: 'Same weight. Aim for smooth reps.' };

  // Big fixed jumps (kettlebells, bands) and 60+ progress reps first (Framework §8.3).
  const repsFirst = isSixtyPlus(ageBand) || loadType === 'kettlebell' || loadType === 'band';
  const readyToAdd = repsFirst ? reps.every((r) => r >= range.hi + 2) : allTop;
  if (!readyToAdd) {
    return { weight: w, action: 'hold', targetReps: repsFirst && allTop ? range.hi + 2 : nextReps,
      note: allTop ? 'Same weight. A couple more reps, then we add weight.' : 'Same weight. Try one more rep per set.' };
  }
  if (loadType === 'bodyweight') {
    return { weight: w, action: 'progress-bodyweight', targetReps: range.hi, note: 'Make it harder: lower slowly for 3 seconds, or try the next level.' };
  }
  const extra = set(settings, 'progression.double_jump_extra_reps');
  const twoSteps = last.rating === 'easy' && !earlyFoundations && !isSixtyPlus(ageBand) && reps.every((r) => r >= range.hi + extra);
  let next = step(loadType, w, twoSteps ? 2 : 1, opts);
  const cap = set(settings, 'progression.max_load_jump_pct') / 100;
  if (twoSteps && (next - w) / w > cap) next = step(loadType, w, 1, opts);   // S9: never jump >10% when a smaller step exists
  if (next === w) return { weight: w, action: 'level-up-check', targetReps: range.hi, note: 'You’ve outgrown this weight. Ready for the next level?' };
  return { weight: next, action: 'increase', targetReps: range.lo, note: 'Nice work. A little heavier this time.' };
}

/** A load cut by pct (comebacks, §13), rounded down to a weight she can actually load. */
function reduceLoad(loadType, weight, pct, opts = {}) {
  if (weight == null || loadType === 'bodyweight' || !pct) return weight;
  return roundDownToStep(loadType, weight * (1 - pct / 100), opts);
}

/** "Scale today" load for a primary (Framework §9): about 10% lighter, rounded down to a loadable weight. */
function scaleTodayWeight(loadType, weight, { settings, ...opts } = {}) {
  return reduceLoad(loadType, weight, set(settings, 'scale_today.load_cut_pct'), opts);
}
return { DB_STEPS, KB_STEPS, BAND_LABELS, DEFAULTS, step, roundDownToStep, findYourWeight, suggestNext, reduceLoad, scaleTodayWeight };
})();

// ── web/engine/session.js ──
const __session = (() => {
// Today's session (Framework §6, §7.2a, §8, §13): the week queue, the week-4/9 decision, and each exercise's dose and
// suggested weight from her history. Pure: dates come in as ISO strings, history comes in as rows.
//
// Pipeline the app runs for a session:
//   baseItems → (makeEasier) → applyWorkarounds → [fetch history for the final exercises] → planSession
//   → applyHold(applySoreness(...)) → (scaleToday)

const { LOWER_PATTERNS, addDays } = __util;
const { slotDose, nextInQueue, adaptiveWeekMode } = __cycle;
const { suggestNext, reduceLoad, BAND_LABELS } = __load;
const { contextFor, eligible } = __resolve;
const DONE = new Set(['done', 'partial']);

/** Session letters in template order. */
const sessionOrder = (template) => template.sessions.map((s) => s.session);

/** A cycle's stored items for one session → resolved items ({slot, exercise, reasons}), in order. Empty slots dropped. */
function baseItems(cycleItems, session, slots, library) {
  const bySlot = Object.fromEntries(slots.filter((s) => s.session === session).map((s) => [s.slot, s]));
  const lib = Object.fromEntries(library.map((e) => [e.id, e]));
  return cycleItems
    .filter((i) => i.session === session && i.exercise_id && bySlot[i.slot] && lib[i.exercise_id])
    .sort((a, b) => a.ord - b.ord)
    .map((i) => ({ slot: bySlot[i.slot], exercise: lib[i.exercise_id], reasons: i.reasons || [] }));
}

/** This week's queue: which sessions are done and which is next (§13: the week is a queue; leftovers drop off). */
function weekStatus(order, weekLogs) {
  const done = order.filter((s) => weekLogs.some((l) => l.session === s && DONE.has(l.status)));
  return { done, next: nextInQueue(order, done), complete: done.length >= order.length };
}

/** One session per day (§13). */
const trainedOn = (logs, day) => logs.some((l) => l.log_date === day && DONE.has(l.status));

/** The dates a cycle week covers: [from, to) as ISO dates. */
const weekWindow = (cycleStart, week) => ({ from: addDays(cycleStart, (week - 1) * 7), to: addDays(cycleStart, week * 7) });

/**
 * The week mode for weeks 4 and 9 (§7.2a), decided from the two weeks before it. Other weeks are 'build'.
 * logs: session_logs rows of this cycle; flagCount: flags raised in those two weeks.
 * A decision already stored on the cycle (cycle.week_modes) wins, so it never changes mid-week.
 */
function weekModeFor({ week, cycle, logs, daysPerWeek, flagCount = 0, settings }) {
  if (week !== 4 && week !== 9) return { mode: 'build', stored: true };
  const saved = cycle.week_modes?.[String(week)];
  if (saved?.mode) return { ...saved, stored: true };
  const window = logs.filter((l) => l.week === week - 1 || l.week === week - 2);
  const done = window.filter((l) => DONE.has(l.status));
  const signals = {
    tooHard: done.filter((l) => l.feel === 'too_hard').length,
    lowEnergy: window.filter((l) => l.energy === 'low').length,
    flags: flagCount,
  };
  const r = adaptiveWeekMode({ week, planned: daysPerWeek * 2, completed: done.length, signals, settings });
  return { ...r, stored: false };
}

/** Working sets of a logged exercise: the sets at the final weight (the anchor after "find your weight"). */
function workingSets(sets, measure) {
  const rows = (sets || []).map((s) => ({ weight: s.weight ?? null, reps: Number(measure === 'time' ? s.seconds : s.reps) || 0 }));
  if (!rows.length) return null;
  const w = rows[rows.length - 1].weight;
  return { weight: w, sets: rows.filter((r) => r.weight === w).map(({ reps }) => ({ reps })) };
}

/** Her last two non-skipped logs for one exercise (newest first) → suggestNext's {last, prevRating}. */
function lastPerformance(history, measure) {
  const usable = (history || []).filter((l) => !l.skipped && l.sets?.length);
  if (!usable.length) return { last: null, prevRating: null };
  const ws = workingSets(usable[0].sets, measure);
  return { last: ws && { ...ws, rating: usable[0].rating ?? null }, prevRating: usable[1]?.rating ?? null };
}

/** How a weight reads to her. */
function weightLabel(loadType, weight) {
  if (loadType === 'bodyweight' || weight == null) return '';
  if (loadType === 'band') return `${BAND_LABELS[weight] ?? 'Band'} band`;
  return `${weight} lb`;
}

function firstNote(loadType, range, measure) {
  if (measure === 'time') return `Hold for ${range.lo}–${range.hi} seconds, breathing the whole time.`;
  if (loadType === 'bodyweight') return `Do ${range.lo}–${range.hi} reps, stopping with 2–3 good reps left.`;
  if (loadType === 'band') return `Pick a band that lets you do ${range.lo}–${range.hi} reps with 2–3 left in the tank.`;
  return null;   // suggestNext's "find your weight" note
}

/**
 * Dose and suggested weight for each item.
 * ctx: { week, weekMode, cycleType, ageBand, dumbbells: number[], comeback: comebackMode(), history: {exerciseId: rows},
 *        settings }
 * Returns items with: dose {sets, reps, rir, time, restSec}, range, measure, weight (suggested; null = she picks),
 * lastWeight, suggestion {action, targetReps, note}.
 */
function planSession(items, ctx) {
  const { week, weekMode = 'build', cycleType, ageBand, dumbbells = [], comeback, history = {}, settings } = ctx;
  return items.map((it) => {
    const ex = it.exercise;
    const measure = ex.measure === 'time' ? 'time' : 'reps';
    let dose = slotDose(it.slot, week, weekMode, settings);
    if (comeback?.setDelta) dose = { ...dose, sets: Math.max(1, dose.sets + comeback.setDelta) };
    const range = measure === 'time' && dose.time ? dose.time : dose.reps;
    const { last, prevRating } = lastPerformance(history[ex.id], measure);
    const s = suggestNext({
      loadType: ex.load_type, last, prevRating, range, ageBand, weekMode, settings,
      lower: LOWER_PATTERNS.has(it.slot.pattern), earlyFoundations: cycleType === 'C1' && week <= 3,
      available: ex.load_type === 'dumbbell' && dumbbells.length ? dumbbells : undefined,
    });
    let weight = s.weight;
    let note = (s.action === 'find' && firstNote(ex.load_type, range, measure)) || s.note;
    if (measure === 'time' && s.action === 'hold') note = 'Same as last time. Try holding a few seconds longer.';
    if (s.action === 'progress-bodyweight') note = 'Make it harder today: lower slowly for 3 seconds on every rep.';
    if (comeback && comeback.mode !== 'none' && weight != null) {
      weight = reduceLoad(ex.load_type, weight, comeback.loadCutPct, { ageBand, available: dumbbells.length ? dumbbells : undefined });
      note = 'Welcome back! A little lighter today so you can ease back in.';
    }
    return { ...it, dose, range, measure, weight, last, lastWeight: last?.weight ?? null,
      suggestion: { action: s.action, targetReps: s.targetReps, note } };
  });
}

/** Soreness hold (§10): where applySoreness marked holdLoad, don't add weight today. */
function applyHold(items) {
  return items.map((it) => (it.holdLoad && it.suggestion?.action === 'increase' && it.lastWeight != null
    ? { ...it, weight: it.lastWeight, suggestion: { ...it.suggestion, action: 'hold', note: 'Same weight today while that area settles.' } }
    : it));
}

/** "Last time: 15 lb × 12, 11" / "Last time: 12, 12 reps" / "Last time: 30, 30 s" — or '' with no history. */
function lastTimeText(loadType, last, measure) {
  if (!last?.sets?.length) return '';
  const reps = last.sets.map((s) => s.reps).join(', ');
  const w = weightLabel(loadType, last.weight);
  const unit = measure === 'time' ? ' s' : ' reps';
  return `Last time: ${w ? `${w} × ${reps}${measure === 'time' ? ' s' : ''}` : `${reps}${unit}`}`;
}

/** Other exercises she could do in this slot today (her "Swap" button): same pattern, eligible, best first. */
function swapOptions(slot, profile, library, currentId, { limit = 4, todayWorkarounds = [] } = {}) {
  const c = contextFor(slot, profile, { todayWorkarounds });
  return library
    .filter((e) => e.pattern === slot.pattern && e.id !== currentId && eligible(e, c))
    .sort((a, b) => (b.level - a.level) || a.id.localeCompare(b.id))
    .slice(0, limit);
}

/** Summary for the finish screen: exercises done, sets done, and whether anything was skipped. */
function sessionSummary(exerciseLogs) {
  const done = exerciseLogs.filter((l) => !l.skipped && l.sets?.length);
  return { exercises: done.length, sets: done.reduce((n, l) => n + l.sets.length, 0), skipped: exerciseLogs.length - done.length };
}
return { sessionOrder, baseItems, weekStatus, trainedOn, weekWindow, weekModeFor, workingSets, lastPerformance, weightLabel, planSession, applyHold, lastTimeText, swapOptions, sessionSummary };
})();

// ── web/engine/progress.js ──
const __progress = (() => {
// Progress and rewards (Framework §13, §15): planned-vs-done by week, the forgiving streak, strength wins and
// milestone messages. Strength only: never weight, BMI or body shape (S10).

const { forgivingStreak, bestStreak } = __adherence;
const { workingSets, weightLabel } = __session;
const DONE = new Set(['done', 'partial']);

/**
 * Week-by-week view of a cycle: [{ week, planned, done }] for weeks 1..currentWeek.
 * A week still in progress counts only what's done so far (planned stays the week's total).
 */
function weeklyCounts(logs, currentWeek, perWeek) {
  const out = [];
  for (let w = 1; w <= Math.min(currentWeek, 9); w++) {
    const done = new Set(logs.filter((l) => l.week === w && DONE.has(l.status)).map((l) => l.session)).size;
    out.push({ week: w, planned: perWeek, done: Math.min(done, perWeek) });
  }
  return out;
}

/**
 * Planned sessions in order for the streak: done ones first within each week, and misses only once a week has ended.
 * @returns {Array<{done: boolean}>}
 */
function plannedSessions(weeks, currentWeek) {
  const out = [];
  for (const w of weeks) {
    for (let i = 0; i < w.done; i++) out.push({ done: true });
    if (w.week < currentWeek) for (let i = w.done; i < w.planned; i++) out.push({ done: false });
  }
  return out;
}

function streaks(weeks, currentWeek) {
  const s = plannedSessions(weeks, currentWeek);
  return { current: forgivingStreak(s), best: bestStreak(s), total: s.filter((x) => x.done).length };
}

/**
 * Strength wins: for each exercise she's logged at least twice, first vs latest working weight (or reps / seconds
 * for bodyweight). Only real improvements are listed, biggest first.
 * exerciseLogs: [{ exercise_id, sets, skipped, created_at }]
 */
function strengthWins(exerciseLogs, library, limit = 6) {
  const lib = Object.fromEntries(library.map((e) => [e.id, e]));
  const by = new Map();
  for (const l of [...exerciseLogs].sort((a, b) => (a.created_at < b.created_at ? -1 : 1))) {
    if (l.skipped || !l.sets?.length || !lib[l.exercise_id]) continue;
    (by.get(l.exercise_id) ?? by.set(l.exercise_id, []).get(l.exercise_id)).push(l);
  }
  const wins = [];
  for (const [id, logs] of by) {
    if (logs.length < 2) continue;
    const ex = lib[id];
    const measure = ex.measure === 'time' ? 'time' : 'reps';
    const a = workingSets(logs[0].sets, measure);
    const b = workingSets(logs[logs.length - 1].sets, measure);
    const best = (ws) => Math.max(...ws.sets.map((s) => s.reps));
    const unit = measure === 'time' ? ' s' : ' reps';
    if (ex.load_type !== 'bodyweight' && a.weight != null && b.weight > a.weight) {
      wins.push({ id, name: ex.name, from: weightLabel(ex.load_type, a.weight), to: weightLabel(ex.load_type, b.weight), gain: (b.weight - a.weight) / a.weight });
    } else if ((ex.load_type === 'bodyweight' || b.weight === a.weight) && best(b) > best(a)) {
      wins.push({ id, name: ex.name, from: `${best(a)}${unit}`, to: `${best(b)}${unit}`, gain: (best(b) - best(a)) / Math.max(1, best(a)) / 2 });
    }
  }
  return wins.sort((x, y) => y.gain - x.gain).slice(0, limit);
}

const MILESTONES = {
  1: 'First workout done. That’s the hardest one.',
  3: 'Three workouts in. You’re building the habit.',
  5: 'Five workouts! Your muscles are already adapting.',
  10: 'Ten workouts. You’re becoming someone who trains.',
  25: 'Twenty-five workouts. That’s real consistency.',
  50: 'Fifty workouts. Strong and consistent.',
};
const EVERYDAY = [
  'Nice work. Every workout helps you keep your muscle.',
  'Done and counted. Showing up is the win.',
  'Another one in the bank. Stronger every week.',
  'That’s how strength gets built: one workout at a time.',
];

/** The reward line after workout number `total`. */
const rewardMessage = (total) => MILESTONES[total] ?? EVERYDAY[total % EVERYDAY.length];
return { weeklyCounts, plannedSessions, streaks, strengthWins, rewardMessage };
})();

// ── web/engine/review.js ──
const __review = (() => {
// End-of-cycle review (Framework §14): the de-identified cycle summary the AI sees, the library options it may pick
// from, the deterministic default proposal (used when the AI is off, fails, or is waiting for review), the default
// recap, and applying a proposal to her levels. Validation lives in review_validate.js.

const { PATTERNS, clamp } = __util;
const { contextFor, eligible } = __resolve;
const { weeklyCounts, streaks, strengthWins } = __progress;
const { workingSets } = __session;
const NEXT_CYCLE = { C1: 'C2', C2: 'C3', C3: 'C3' };
const CYCLE_NAMES = { C1: 'Foundations', C2: 'Building', C3: 'Strong & Consistent' };
const PATTERN_NAMES = {
  SQ: 'squat', HI: 'hip hinge', SL: 'single-leg', HP: 'push', VP: 'overhead press', HR: 'row', VR: 'pulldown',
  CA: 'carry', CO: 'core', BA: 'balance', HA: 'hip strength', AR: 'arms',
};
const DONE = new Set(['done', 'partial']);
const count = (arr) => arr.reduce((m, k) => ({ ...m, [k]: (m[k] ?? 0) + 1 }), {});

/** The engine's profile shape from a patients row (same as the app's engineProfile). */
const reviewProfile = (p) => ({
  equipment: p.equipment || [], patternLevels: p.pattern_levels || {}, workarounds: p.workarounds || [],
  restrictions: p.restrictions || [], floorOk: Boolean(p.floor_ok),
});

/**
 * De-identified summary of one cycle: no name, email, dates of birth, free text or clinic. Counts, levels, trends.
 * @param {object} d { patient, cycle, template, logs, exerciseLogs, flags, adjustments, library, reflection }
 *   reflection: { worked: [], in_the_way: [], adjust: string, focus: string, days?: number, minutes?: number }
 */
function cycleSummary({ patient, cycle, template, logs, exerciseLogs = [], flags = [], adjustments = [], library, reflection = {} }) {
  const perWeek = template?.days_per_week ?? patient.days_per_week ?? 3;
  const weeks = weeklyCounts(logs, 9, perWeek);
  const s = streaks(weeks, 10);
  const planned = weeks.reduce((n, w) => n + w.planned, 0);
  const done = logs.filter((l) => DONE.has(l.status));
  const lib = Object.fromEntries(library.map((e) => [e.id, e]));
  const patterns = {};
  for (const p of PATTERNS) {
    const mine = exerciseLogs.filter((l) => lib[l.exercise_id]?.pattern === p && !l.skipped && l.sets?.length)
      .sort((a, b) => (a.created_at < b.created_at ? -1 : 1));
    if (!mine.length && !(p in (patient.pattern_levels || {}))) continue;
    const ex = mine.length ? lib[mine[mine.length - 1].exercise_id] : null;
    const measure = ex?.measure === 'time' ? 'time' : 'reps';
    const first = mine.length ? workingSets(mine[0].sets, measure) : null;
    const last = mine.length ? workingSets(mine[mine.length - 1].sets, measure) : null;
    const top = (ws) => (ws ? Math.max(...ws.sets.map((x) => x.reps)) : null);
    patterns[p] = {
      level: patient.pattern_levels?.[p] ?? 1,
      sessions: mine.length,
      exercises: [...new Set(mine.map((l) => l.exercise_id))],
      ratings: count(mine.map((l) => l.rating).filter(Boolean)),
      first: first ? { weight: first.weight, best: top(first) } : null,
      last: last ? { weight: last.weight, best: top(last) } : null,
      load_type: ex?.load_type ?? null,
    };
  }
  const checked = done.filter((l) => l.feel);
  const area = (field) => count(done.flatMap((l) => l[field] || []));
  return {
    cycle: { number: cycle.cycle_no, type: cycle.cycle_type, template: cycle.template_id, days_per_week: perWeek,
      session_minutes: cycle.session_minutes, week_modes: Object.fromEntries(Object.entries(cycle.week_modes || {}).map(([w, m]) => [w, m?.mode])) },
    patient: {
      age_band: patient.age_band, experience: patient.experience, goal: patient.goal, setup: patient.setup,
      equipment: patient.equipment || [], restrictions: patient.restrictions || [], workarounds: patient.workarounds || [],
      floor_ok: Boolean(patient.floor_ok), dumbbells: patient.dumbbells_available || [],
    },
    adherence: { planned, completed: weeks.reduce((n, w) => n + w.done, 0), by_week: weeks.map((w) => w.done),
      pct: planned ? Math.round((weeks.reduce((n, w) => n + w.done, 0) / planned) * 100) : 0,
      best_streak: s.best, scaled: done.filter((l) => l.scaled).length,
      skips: count(logs.filter((l) => l.status === 'skipped' && l.skip_reason).map((l) => l.skip_reason)) },
    checkins: { count: checked.length, feel: count(checked.map((l) => l.feel)),
      low_energy: logs.filter((l) => l.energy === 'low').length,
      sore_a_lot: count(done.filter((l) => l.soreness === 'a_lot').flatMap((l) => l.sore_areas || [])),
      sore_any: area('sore_areas'), workarounds: area('workaround_areas') },
    flags: count(flags.map((f) => f.type)),
    adjustments: count(adjustments.map((a) => a.type)),
    patterns,
    strength_wins: strengthWins(exerciseLogs, library, 3).map((w) => ({ exercise: w.name, from: w.from, to: w.to })),
    reflection: { worked: reflection.worked || [], in_the_way: reflection.in_the_way || [], adjust: reflection.adjust || null,
      focus: reflection.focus || null, days: reflection.days ?? null },
  };
}

/** Exercises she could be given per pattern next cycle (her equipment, restrictions, floor rule; level ≤ current + 1). */
function libraryOptions(profile, library, perPattern = 8) {
  const out = {};
  for (const p of PATTERNS) {
    const level = (profile.patternLevels?.[p] ?? 1) + 1;
    const ctx = contextFor({ pattern: p }, { ...profile, patternLevels: { ...profile.patternLevels, [p]: level } });
    const opts = library.filter((e) => e.pattern === p && eligible(e, ctx))
      .sort((a, b) => (b.level - a.level) || a.id.localeCompare(b.id)).slice(0, perPattern)
      .map((e) => ({ id: e.id, name: e.name, level: e.level }));
    if (opts.length) out[p] = opts;
  }
  return out;
}

/** The default recap: specific, warm, no weight talk. */
function defaultRecap(summary, nextType, days) {
  const a = summary.adherence;
  const parts = [`You finished ${a.completed} workout${a.completed === 1 ? '' : 's'} in Cycle ${summary.cycle.number}.`];
  if (a.best_streak >= 3) parts.push(`Your best streak was ${a.best_streak} in a row.`);
  const w = summary.strength_wins[0];
  if (w) parts.push(`Biggest win: ${w.exercise}, from ${w.from} to ${w.to}.`);
  else if (a.completed) parts.push('You’ve been building the habit, and that’s what strength is made of.');
  parts.push(nextType === summary.cycle.type
    ? `Next up: another round of ${CYCLE_NAMES[nextType]} with fresh energy, ${days} days a week.`
    : `Next up: ${CYCLE_NAMES[nextType]}, ${days} days a week.`);
  parts.push('Keep showing up. That’s what makes you stronger.');
  return parts.join(' ');
}

/**
 * The deterministic default (Framework §14): next cycle type in sequence, levels unchanged, the template's default
 * exercises, her own days per week, her chosen focus.
 */
function defaultProposal(summary) {
  const nextType = NEXT_CYCLE[summary.cycle.type] ?? summary.cycle.type;
  const days = summary.reflection.days ?? summary.cycle.days_per_week;
  return {
    cycle_type: nextType, days_per_week: days, level_changes: [], swaps: [],
    recap: defaultRecap(summary, nextType, days), focus: summary.reflection.focus ?? 'Keep building the habit', flags: [],
  };
}

/** Her levels after a proposal's level changes (each ±1, clamped 1–4). */
function applyLevelChanges(levels, changes = []) {
  const out = { ...levels };
  for (const c of changes) out[c.pattern] = clamp((out[c.pattern] ?? 1) + Math.sign(c.change), 1, 4);
  return out;
}

/**
 * Slots for the next cycle with her swaps applied: the first slot (in session order) of each swapped pattern prefers
 * the chosen exercise. Other slots are untouched.
 */
function slotsWithSwaps(slots, swaps = []) {
  const done = new Set();
  return [...slots].sort((a, b) => (a.session === b.session ? a.ord - b.ord : a.session < b.session ? -1 : 1)).map((s) => {
    const sw = swaps.find((x) => x.pattern === s.pattern);
    if (!sw || done.has(s.pattern)) return s;
    done.add(s.pattern);
    return { ...s, prefer_ids: [sw.exercise_id, ...(s.prefer_ids || [])] };
  });
}

/** Plain-language lines for the patient: what changes next cycle. */
function proposalLines(p, library) {
  const lib = Object.fromEntries(library.map((e) => [e.id, e]));
  const lines = [];
  for (const c of p.level_changes || []) {
    lines.push(`${PATTERN_NAMES[c.pattern] ?? c.pattern}: ${c.change > 0 ? 'one level up' : 'one level easier'}${c.evidence ? `. ${c.evidence}` : ''}`);
  }
  for (const s of p.swaps || []) lines.push(`New exercise for ${PATTERN_NAMES[s.pattern] ?? s.pattern}: ${lib[s.exercise_id]?.name ?? s.exercise_id}`);
  return lines;
}
return { NEXT_CYCLE, CYCLE_NAMES, PATTERN_NAMES, reviewProfile, cycleSummary, libraryOptions, defaultRecap, defaultProposal, applyLevelChanges, slotsWithSwaps, proposalLines };
})();

// ── web/engine/review_validate.js ──
const __review_validate = (() => {
// Validating an AI cycle proposal (Framework §14 "may / may not", S-rules, admin bounds), plus the tool schema and
// prompt the AI is called with. A proposal with errors is never applied as-is; one with review items is valid but
// outside the auto-apply bounds. Either way it goes to the admin queue and she gets the default until it's decided.

const { PATTERNS } = __util;
const { contextFor, eligible } = __resolve;
const { NEXT_CYCLE, CYCLE_NAMES, PATTERN_NAMES, applyLevelChanges } = __review;
const DEFAULTS = { 'ai.max_exercise_swaps': 3, 'ai.repeat_cycle_below_adherence_pct': 50, 'ai.recap_max_words': 120 };
const cfg = (s, k) => (s && s[k] != null ? Number(s[k]) : DEFAULTS[k]);

/** Words the recap and focus must never use (§14 "may not", S10, §15 tone). Exercise loads like "15 lb" are fine. */
const BANNED = /\b(weight[- ]?loss|lose weight|losing weight|lost \d+|pounds? (?:lost|down|off)|bmi|body mass|calorie|diet|nutrition|protein shake|medication|meds|dose|ozempic|wegovy|semaglutide|tirzepatide|mounjaro|zepbound|glp-?1|injur\w*|diagnos\w*|skinny|slim(?:mer)?|tone[ds]?|toning|belly|thighs?|burn|fat|beginner|advanced|failed|missed)\b/i;

const wordCount = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;

/** Coerce the AI's tool input into a proposal shape (or null if it isn't one). */
function normalizeProposal(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const arr = (x) => (Array.isArray(x) ? x : []);
  return {
    cycle_type: String(raw.cycle_type ?? '').toUpperCase(),
    days_per_week: Number(raw.days_per_week),
    level_changes: arr(raw.level_changes).map((c) => ({ pattern: String(c?.pattern ?? '').toUpperCase(), change: Number(c?.change), evidence: String(c?.evidence ?? '').slice(0, 200) })),
    swaps: arr(raw.swaps).map((s) => ({ pattern: String(s?.pattern ?? '').toUpperCase(), exercise_id: String(s?.exercise_id ?? '').toUpperCase(), reason: String(s?.reason ?? '').slice(0, 200) })),
    recap: String(raw.recap ?? '').trim(),
    focus: String(raw.focus ?? '').trim(),
    flags: arr(raw.flags).map((f) => ({ reason: String(f?.reason ?? f ?? '').slice(0, 300) })).filter((f) => f.reason),
  };
}

/**
 * @param {object} p      normalized proposal
 * @param {object} ctx    { summary, library, profile (engine shape), settings }
 * @returns {{ errors: string[], review: string[] }}
 */
function validateProposal(p, { summary, library, profile, settings }) {
  const errors = [];
  const review = [];
  if (!p) return { errors: ['not a proposal'], review };
  const cur = summary.cycle.type;
  const adherence = summary.adherence.pct;

  // Cycle type: same (repeat / variant) or the next in sequence. Never backwards, never skipping one.
  if (!CYCLE_NAMES[p.cycle_type]) errors.push(`unknown cycle type ${p.cycle_type}`);
  else if (p.cycle_type !== cur && p.cycle_type !== NEXT_CYCLE[cur]) errors.push(`cycle type ${cur} → ${p.cycle_type} is not allowed`);
  else if (p.cycle_type !== cur && adherence < cfg(settings, 'ai.repeat_cycle_below_adherence_pct')) {
    review.push(`moves to ${p.cycle_type} with ${adherence}% adherence (below ${cfg(settings, 'ai.repeat_cycle_below_adherence_pct')}%)`);
  }

  // Days per week: 2–4; 4 only from C2 on; never more than one day above what she chose; she confirms in the app.
  if (![2, 3, 4].includes(p.days_per_week)) errors.push(`days per week ${p.days_per_week} is not 2, 3 or 4`);
  else {
    if (p.days_per_week === 4 && p.cycle_type === 'C1') errors.push('4 days a week is not offered in Foundations');
    const base = summary.reflection.days ?? summary.cycle.days_per_week;
    if (p.days_per_week > base) review.push(`recommends ${p.days_per_week} days (she chose ${base})`);
    if (p.days_per_week > summary.cycle.days_per_week && adherence < 75) review.push(`more days with ${adherence}% adherence`);
  }

  // Level changes: ±1, one per pattern, a real pattern, the result within 1–4.
  const seen = new Set();
  for (const c of p.level_changes) {
    if (!PATTERNS.includes(c.pattern)) { errors.push(`unknown pattern ${c.pattern}`); continue; }
    if (seen.has(c.pattern)) errors.push(`more than one level change for ${c.pattern}`);
    seen.add(c.pattern);
    if (c.change !== 1 && c.change !== -1) { errors.push(`level change for ${c.pattern} must be +1 or -1`); continue; }
    const now = profile.patternLevels?.[c.pattern] ?? 1;
    if (now + c.change < 1 || now + c.change > 4) errors.push(`${c.pattern} level ${now} ${c.change > 0 ? '+' : ''}${c.change} is out of range`);
    if (!c.evidence) review.push(`no evidence given for the ${c.pattern} change`);
    const pat = summary.patterns[c.pattern];
    if (c.change > 0 && (pat?.ratings?.hard ?? 0) > (pat?.ratings?.good ?? 0) + (pat?.ratings?.easy ?? 0)) review.push(`${c.pattern} up despite mostly Hard ratings`);
    if (c.change > 0 && (summary.flags.pain || summary.flags.dizzy)) review.push(`${c.pattern} up in a cycle with pain or dizzy flags`);
  }
  if (p.level_changes.length > 4) review.push(`${p.level_changes.length} level changes (more than 4)`);

  // Swaps: within her filtered library, same pattern, a level she'll be at, at most the admin limit.
  const levels = applyLevelChanges(profile.patternLevels || {}, p.level_changes.filter((c) => PATTERNS.includes(c.pattern) && Math.abs(c.change) === 1));
  const lib = Object.fromEntries(library.map((e) => [e.id, e]));
  const max = cfg(settings, 'ai.max_exercise_swaps');
  if (p.swaps.length > max) errors.push(`${p.swaps.length} exercise swaps (the limit is ${max})`);
  const swapped = new Set();
  for (const s of p.swaps) {
    const ex = lib[s.exercise_id];
    if (!ex) { errors.push(`exercise ${s.exercise_id} is not in the library`); continue; }
    if (ex.pattern !== s.pattern) errors.push(`${s.exercise_id} is not a ${s.pattern} exercise`);
    if (swapped.has(s.pattern)) errors.push(`two swaps for ${s.pattern}`);
    swapped.add(s.pattern);
    const ctx = contextFor({ pattern: ex.pattern }, { ...profile, patternLevels: levels });
    if (!eligible(ex, ctx)) errors.push(`${s.exercise_id} doesn't fit her equipment, restrictions or level`);
  }

  // Words: length, banned topics (weight, BMI, medication, body shape, medical claims, labels).
  if (!p.recap) errors.push('no recap');
  if (wordCount(p.recap) > cfg(settings, 'ai.recap_max_words')) errors.push(`recap is ${wordCount(p.recap)} words (limit ${cfg(settings, 'ai.recap_max_words')})`);
  for (const [name, text] of [['recap', p.recap], ['focus', p.focus], ...p.level_changes.map((c) => ['evidence', c.evidence])]) {
    const m = BANNED.exec(text || '');
    if (m) errors.push(`${name} uses "${m[0]}"`);
  }
  if (!p.focus || p.focus.length > 80) errors.push('focus must be 1–80 characters');
  if (p.flags.length) review.push(...p.flags.map((f) => `AI flag: ${f.reason}`));
  return { errors, review };
}

/** The tool the model must call (forced), so the output is structured. */
const PROPOSAL_TOOL = {
  name: 'propose_next_cycle',
  description: 'Propose the patient’s next 9-week strength cycle within the program rules.',
  input_schema: {
    type: 'object',
    required: ['cycle_type', 'days_per_week', 'level_changes', 'swaps', 'recap', 'focus', 'flags'],
    properties: {
      cycle_type: { type: 'string', enum: ['C1', 'C2', 'C3'], description: 'Same type (repeat with fresh exercises) or the next in sequence.' },
      days_per_week: { type: 'integer', enum: [2, 3, 4] },
      level_changes: { type: 'array', items: { type: 'object', required: ['pattern', 'change', 'evidence'], properties: {
        pattern: { type: 'string', enum: PATTERNS }, change: { type: 'integer', enum: [-1, 1] },
        evidence: { type: 'string', description: 'One sentence citing her data.' } } } },
      swaps: { type: 'array', items: { type: 'object', required: ['pattern', 'exercise_id', 'reason'], properties: {
        pattern: { type: 'string', enum: PATTERNS }, exercise_id: { type: 'string', description: 'An id from library_options for that pattern.' },
        reason: { type: 'string' } } } },
      recap: { type: 'string', description: 'To her, second person, warm and specific, at most 120 words. No weight, BMI, body shape, medication or nutrition.' },
      focus: { type: 'string', description: 'A short focus for the next cycle, at most 80 characters.' },
      flags: { type: 'array', items: { type: 'object', required: ['reason'], properties: { reason: { type: 'string' } } },
        description: 'Anything the program team should look at.' },
    },
  },
};

/** System and user messages for the review. `brief` is the private coach brief (imported with the content). */
function buildPrompt(summary, options, brief, settings) {
  const system = [
    'You are the strength coach for a clinic program for adults, mostly women 40–60, who are losing weight with medical support.',
    'You review one 9-week cycle and propose the next one by calling propose_next_cycle. Follow these rules exactly:',
    `- cycle_type: the same type (a repeat with fresh exercises) or the next in sequence (C1 Foundations → C2 Building → C3 Strong & Consistent → C3 again). Repeat when adherence is under ${cfg(settings, 'ai.repeat_cycle_below_adherence_pct')}% or most sessions felt too hard.`,
    '- days_per_week: 2, 3 or 4 (4 only from C2 on). Start from the days she chose; she confirms.',
    '- level_changes: at most one per movement pattern, +1 or -1 only, each with one sentence of evidence from her data. Raise a level only with steady progress, mostly Good/Easy ratings and no pain flags on that pattern.',
    `- swaps: at most ${cfg(settings, 'ai.max_exercise_swaps')}, only ids listed in library_options for that pattern, to freshen things up or work around a sore area.`,
    `- recap: written to her in plain, warm, specific language, at most ${cfg(settings, 'ai.recap_max_words')} words. Celebrate consistency and strength. Never mention body weight, BMI, body shape, appearance, medication, diet or nutrition, and give no medical advice.`,
    '- flags: anything worrying (repeated pain, dizziness, a sharp drop in attendance) for the program team.',
    brief ? `\nProgram brief:\n${brief}` : '',
  ].join('\n');
  const user = `Cycle summary (de-identified):\n${JSON.stringify(summary)}\n\nlibrary_options (per pattern, ids she may be given):\n${JSON.stringify(options)}\n\nPattern names: ${JSON.stringify(PATTERN_NAMES)}`;
  return { system, user };
}
return { DEFAULTS, BANNED, normalizeProposal, validateProposal, PROPOSAL_TOOL, buildPrompt };
})();

