const DEFAULT_MODEL = 'claude-sonnet-5-5';
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};
const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });

function secretKey() {
  try {
    const keys = JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS') ?? '{}');
    const first = keys.default ?? Object.values(keys)[0];
    if (first) return String(first);
  } catch { /* fall back to the legacy key */ }
  return Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
}

async function callAnthropic({ system, user }, tool, model) {
  const key = Deno.env.get('ANTHROPIC_API_KEY');
  if (!key) return null;
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: { 'x-api-key': key, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: JSON.stringify({ model, max_tokens: 1500, system, messages: [{ role: 'user', content: user }],
      tools: [tool], tool_choice: { type: 'tool', name: tool.name } }),
    signal: AbortSignal.timeout(45000),
  });
  if (!res.ok) throw new Error(`anthropic ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const out = await res.json();
  const call = (out.content || []).find((c) => c.type === 'tool_use');
  if (!call) throw new Error('no tool call in the response');
  return call.input;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  if (req.method !== 'POST') return json({ error: 'method' }, 405);
  const token = (req.headers.get('Authorization') ?? '').replace(/^Bearer\s+/i, '');
  const db = createClient(Deno.env.get('SUPABASE_URL'), secretKey(), { auth: { persistSession: false, autoRefreshToken: false } });
  const model = Deno.env.get('GLP1_AI_MODEL') || DEFAULT_MODEL;
  const deps = {
    db, model, today: new Date().toISOString().slice(0, 10),
    getUser: async (t) => { const { data, error } = await db.auth.getUser(t); return error ? null : data?.user ?? null; },
    callModel: (prompt, tool) => callAnthropic(prompt, tool, model),
  };
  const body = await req.json().catch(() => ({}));
  try {
    const r = await reviewCycle({ token, body }, deps);
    return json(r.body, r.status);
  } catch (e) {
    console.error(e);
    return json({ error: 'server' }, 500);
  }
});
